public class Thermostat {
    private double temperature;

    public Thermostat(double temperature) {
        this.temperature = temperature;
    }

    public double getTemperature() {
        return temperature;
    }

    public String getStatus() {
        if (temperature < 68.0) {
            return "HEATING";
        }
        if (temperature > 76.0) {
            return "COOLING";
        }
        return "IDLE";
    }
}
